package org.apache.commons.codec.binary;

import java.io.*;
import java.math.*;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.codec.BinaryDecoder;
import org.apache.commons.codec.BinaryEncoder;
import org.apache.commons.codec.DecoderException;
import org.apache.commons.codec.EncoderException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Base64_encodeBase64_TriageGen2Test {

    @Test
    public void testEncodeBase64_EmptyInput() {
        byte[] input = new byte[0];
        // Testing the branch: if (false || binaryData.length == 0)
        byte[] result = Base64.encodeBase64(input, false, false, 100);
        assertArrayEquals(input, result);
    }

    @Test
    public void testEncodeBase64_NormalEncoding() {
        byte[] input = "Hello World".getBytes();
        // Standard encoding: not chunked, not urlSafe
        byte[] result = Base64.encodeBase64(input, false, false, 100);
        String expected = "SGVsbG8gV29ybGQ=";
        assertEquals(expected, new String(result).trim());
    }

    @Test
    public void testEncodeBase64_UrlSafe() {
        // Use input that produces '+' or '/' in standard Base64
        // Standard: "+/==" -> URL Safe: "-_=="
        byte[] input = new byte[]{(byte) 0xfb, (byte) 0xff}; 
        byte[] result = Base64.encodeBase64(input, false, true, 100);
        String resultStr = new String(result).trim();
        assertFalse("Should not contain + or /", resultStr.contains("+") || resultStr.contains("/"));
    }

    @Test
    public void testEncodeBase64_Chunked() {
        // Testing isChunked = true
        // This uses the Base64(urlSafe) constructor via the logic in the method
        byte[] input = "ChunkedDataTest".getBytes();
        // We set a large maxResultSize to avoid exception
        byte[] result = Base64.encodeBase64(input, true, false, 1000);
        assertNotNull(result);
        assertTrue(result.length > 0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testEncodeBase64_ExceedsMaxSize() {
        byte[] input = new byte[100];
        // Set maxResultSize very small so that len > maxResultSize
        // len will be at least 133 (approx for 100 bytes)
        Base64.encodeBase64(input, false, false, 10);
    }

    @Test
    public void testEncodeBase64_ExactMaxSize() {
        byte[] input = "abc".getBytes(); // "YWJj" is 4 bytes
        // Test boundary condition where len == maxResultSize
        // We need to calculate or approximate the length. 
        // For "abc", Base64 is "YWJj" (4 bytes)
        Base64.encodeBase64(input, false, false, 4);
    }

    @Test
    public void testEncodeBase64_ChunkedUrlSafe() {
        byte[] input = "ChunkedAndUrlSafe".getBytes();
        // Testing combined flags
        byte[] result = Base64.encodeBase64(input, true, true, 1000);
        assertNotNull(result);
    }
}
